import AccessorArray = require( '@stdlib/array/base/accessor' );
import gcross = require( './index' );


// TESTS //

// The function returns a numeric array...
{
	const x = new Float64Array( 3 );
	const y = new Float64Array( 3 );
	const z = new Float64Array( 3 );

	gcross( x, 1, y, 1, z, 1 ); // $ExpectType Float64Array
	gcross( new AccessorArray( x ), 1, new AccessorArray( y ), 1, new AccessorArray( z ), 1 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a numeric array...
{
	const y = new Float64Array( 3 );
	const z = new Float64Array( 3 );

	gcross( 10, 1, y, 1, z, 1 ); // $ExpectError
	gcross( '10', 1, y, 1, z, 1 ); // $ExpectError
	gcross( true, 1, y, 1, z, 1 ); // $ExpectError
	gcross( false, 1, y, 1, z, 1 ); // $ExpectError
	gcross( null, 1, y, 1, z, 1 ); // $ExpectError
	gcross( undefined, 1, y, 1, z, 1 ); // $ExpectError
	gcross( [ '1' ], 1, y, 1, z, 1 ); // $ExpectError
	gcross( {}, 1, y, 1, z, 1 ); // $ExpectError
	gcross( ( x: number ): number => x, 1, y, 1, z, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Float64Array( 3 );
	const y = new Float64Array( 3 );
	const z = new Float64Array( 3 );

	gcross( x, '10', y, 1, z, 1 ); // $ExpectError
	gcross( x, true, y, 1, z, 1 ); // $ExpectError
	gcross( x, false, y, 1, z, 1 ); // $ExpectError
	gcross( x, null, y, 1, z, 1 ); // $ExpectError
	gcross( x, undefined, y, 1, z, 1 ); // $ExpectError
	gcross( x, [], y, 1, z, 1 ); // $ExpectError
	gcross( x, {}, y, 1, z, 1 ); // $ExpectError
	gcross( x, ( x: number ): number => x, y, 1, z, 1 ); // $ExpectError
}

