// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 3 );
	const y = new Float64Array( 3 );
	const z = new Float64Array( 3 );

	gcross(); // $ExpectError
	gcross( x ); // $ExpectError
	gcross( x, 1 ); // $ExpectError
	gcross( x, 1, y ); // $ExpectError
	gcross( x, 1, y, 1 ); // $ExpectError
	gcross( x, 1, y, 1, z ); // $ExpectError
	gcross( x, 1, y, 1, z, 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a numeric array...
{
	const x = new Float64Array( 3 );
	const y = new Float64Array( 3 );
	const z = new Float64Array( 3 );

	gcross.ndarray( x, 1, 0, y, 1, 0, z, 1, 0 ); // $ExpectType Float64Array
	gcross.ndarray( new AccessorArray( x ), 1, 0, new AccessorArray( y ), 1, 0, new AccessorArray( z ), 1, 0 ); // $ExpectType AccessorArray<number>
}

