	gcross.ndarray( x, 1, 0, y ); // $ExpectError
	gcross.ndarray( x, 1, 0, y, 1 ); // $ExpectError
	gcross.ndarray( x, 1, 0, y, 1, 0 ); // $ExpectError
	gcross.ndarray( x, 1, 0, y, 1, 0, z ); // $ExpectError
	gcross.ndarray( x, 1, 0, y, 1, 0, z, 1 ); // $ExpectError
